exec('''"""СЦЕНА: Выбор сохраненияLINESPLITTER - Интерфейс создания новой записи прохожденияLINESPLITTER - Возвращение в предыдущее меню"""LINESPLITTERLINESPLITTER# -- импорт модулейLINESPLITTERimport timeLINESPLITTERLINESPLITTERimport arcadeLINESPLITTERimport arcade.guiLINESPLITTERimport arcade.gui.widgets.buttonsLINESPLITTERimport arcade.gui.widgets.layoutLINESPLITTERfrom arcade.experimental import ShadertoyLINESPLITTERfrom arcade.gui import UIStyleBaseLINESPLITTERLINESPLITTERLINESPLITTERclass CustomButtonStyle(UIStyleBase):LINESPLITTER    font_size: float = 18LINESPLITTER    font_color: tuple = (255, 255, 255, 255)LINESPLITTER    font_name: tuple = ("Roboto", "Arial", "calibri")LINESPLITTERLINESPLITTERLINESPLITTERdefault_button_styles = {LINESPLITTER    "normal": CustomButtonStyle(),LINESPLITTER    "hover": CustomButtonStyle(),LINESPLITTER    "press": CustomButtonStyle()LINESPLITTER}LINESPLITTERLINESPLITTERLINESPLITTER# -- класс сценыLINESPLITTERclass Main(arcade.View):LINESPLITTER    # -- инициализацияLINESPLITTER    def __init__(self, config):LINESPLITTER        super().__init__()LINESPLITTERLINESPLITTER        self.conf = configLINESPLITTER        self.scaling = self.width / 800LINESPLITTER        self.conf.assets.font(\'LeticeaBumsteadCyrillic\')LINESPLITTERLINESPLITTER        # настройки сценыLINESPLITTER        self.background_color = arcade.color.Color(33, 23, 41)LINESPLITTERLINESPLITTER        # настройка интерфейсаLINESPLITTER        self.ui = arcade.gui.UIManager()LINESPLITTERLINESPLITTER        self.layout = arcade.gui.UIAnchorLayout()LINESPLITTERLINESPLITTER        self.button_column = arcade.gui.UIBoxLayout(space_between=10)LINESPLITTERLINESPLITTER        title_texture = self.conf.assets.texture(\'title\')LINESPLITTER        self.title = arcade.gui.UIImage(LINESPLITTER            texture=title_texture,LINESPLITTER        )LINESPLITTERLINESPLITTER        self.exit_button = arcade.gui.UITextureButton(LINESPLITTER            text=\'Назад\',LINESPLITTER            texture=self.conf.assets.texture(\'button\'),LINESPLITTER            texture_hovered=self.conf.assets.texture(\'button_hovered\'),LINESPLITTER            scale=0.5,LINESPLITTER            style=default_button_stylesLINESPLITTER        )LINESPLITTER        self.new_button = arcade.gui.UITextureButton(LINESPLITTER            text=\'Новый\',LINESPLITTER            texture=self.conf.assets.texture(\'button\'),LINESPLITTER            texture_hovered=self.conf.assets.texture(\'button_hovered\'),LINESPLITTER            scale=0.5,LINESPLITTER            style=default_button_stylesLINESPLITTER        )LINESPLITTER        self.exit_button.on_click = self.exit_button_clickLINESPLITTER        self.new_button.on_click = self.new_button_clickLINESPLITTERLINESPLITTER        self.button_column.add(self.title)LINESPLITTER        self.init_saves()LINESPLITTER        self.button_column.add(self.new_button)LINESPLITTER        self.button_column.add(self.exit_button)LINESPLITTERLINESPLITTER        self.layout.add(self.button_column)LINESPLITTERLINESPLITTER        self.ui.add(self.layout)LINESPLITTERLINESPLITTER        if self.conf.DEBUG:LINESPLITTER            self.panel = self.conf.utils.ui.DebugPanel(self.conf.logger)LINESPLITTERLINESPLITTER        self.shadertoy = NoneLINESPLITTERLINESPLITTER        self.mouse = arcade.Sprite(path_or_texture=self.conf.assets.texture(\'cursor\'), scale=0.1)LINESPLITTERLINESPLITTER        self.mouse_sprite_list = arcade.SpriteList()LINESPLITTER        self.mouse_sprite_list.append(self.mouse)LINESPLITTERLINESPLITTER        # вызов on_resize, для финальной инициализацииLINESPLITTER        self.on_resize(int(self.width), int(self.height))LINESPLITTERLINESPLITTER    # -- отрисовкаLINESPLITTER    def init_saves(self):LINESPLITTER        data = self.conf.data.dataLINESPLITTERLINESPLITTER        # - Создание кнопок для каждого существующего мираLINESPLITTER        if \'worlds\' in data:LINESPLITTER            c = 0LINESPLITTER            for world in data[\'worlds\']:LINESPLITTER                button = arcade.gui.UITextureButton(LINESPLITTER                    text=world[\'name\'],LINESPLITTER                    texture=self.conf.assets.texture(\'button\'),LINESPLITTER                    texture_hovered=self.conf.assets.texture(\'button_hovered\'),LINESPLITTER                    scale=0.5,LINESPLITTER                    style=default_button_stylesLINESPLITTER                )LINESPLITTER                button.on_click = lambda x, idx=c: self.load_save(idx)LINESPLITTER                self.button_column.add(button)LINESPLITTER                c += 1LINESPLITTERLINESPLITTER    def load_save(self, data):LINESPLITTER        self.conf.current_world = dataLINESPLITTER        self.conf.logger.log(f\'Загрузка мира {data}\')LINESPLITTERLINESPLITTER        from .game import Main as next_viewLINESPLITTER        arcade.play_sound(self.conf.assets.effect(\'button_click\'))LINESPLITTER        prev_view = next_view(self.conf)LINESPLITTER        self.window.show_view(prev_view)LINESPLITTERLINESPLITTER    def on_draw(self):LINESPLITTER        self.draw_all()LINESPLITTER        self.mouse_sprite_list.draw()LINESPLITTERLINESPLITTER    def draw_all(self):LINESPLITTER        self.clear()LINESPLITTER        self.ui.draw()LINESPLITTERLINESPLITTER        if self.conf.DEBUG:LINESPLITTER            self.panel.draw()LINESPLITTERLINESPLITTER    # -- обновление состоянияLINESPLITTER    def on_update(self, delta_time: float):LINESPLITTER        self.shadertoy.program[\'time\'] = int(time.time() * 10000)LINESPLITTERLINESPLITTER    # -- обработка ввода пользователяLINESPLITTER    def on_key_press(self, key, key_modifiers):LINESPLITTER        if key == self.conf.KEYS[\'fullscreen\']:LINESPLITTER            self.window.set_fullscreen(not self.window.fullscreen)LINESPLITTERLINESPLITTER    def exit_button_click(self, event):LINESPLITTER        from .menu import Main as play_viewLINESPLITTER        arcade.play_sound(self.conf.assets.effect(\'button_click\'))LINESPLITTER        next_view = play_view(self.conf)LINESPLITTER        self.window.show_view(next_view)LINESPLITTERLINESPLITTER    def new_button_click(self, event):LINESPLITTER        from .create_save import Main as play_viewLINESPLITTER        arcade.play_sound(self.conf.assets.effect(\'button_click\'))LINESPLITTER        next_view = play_view(self.conf)LINESPLITTER        self.window.show_view(next_view)LINESPLITTERLINESPLITTER    # -- Системные событияLINESPLITTER    def on_show_view(self):LINESPLITTER        self.ui.enable()LINESPLITTER        self.conf.music.ensure_playing(\'menu\')LINESPLITTER        self.conf.player = NoneLINESPLITTER        self.conf.enemy = NoneLINESPLITTERLINESPLITTER        if self.conf.DEBUG:LINESPLITTER            self.panel.enable()LINESPLITTERLINESPLITTER        self.on_resize(int(self.width), int(self.height))LINESPLITTERLINESPLITTER    def on_hide_view(self):LINESPLITTER        self.ui.disable()LINESPLITTERLINESPLITTER        if self.conf.DEBUG:LINESPLITTER            self.panel.disable()LINESPLITTERLINESPLITTER    def on_resize(self, width: int, height: int):LINESPLITTER        super().on_resize(width, height)LINESPLITTER        self.scaling = min(width / 800, height / 600)LINESPLITTER        shader_file_path = self.conf.SHADER_FOLDER / \'background.glsl\'LINESPLITTER        window_size = self.window.get_size()LINESPLITTER        self.shadertoy = Shadertoy.create_from_file(window_size, shader_file_path)LINESPLITTERLINESPLITTER    def on_mouse_motion(self, x: int, y: int, dx: int, dy: int):LINESPLITTER        self.mouse.position = self.window.current_camera.unproject((x, y))LINESPLITTER'''.replace('LINESPLITTER', '\n'))